<script setup lang="ts">
import { computed, ref } from 'vue';
import { AlertTriangleIcon, ChevronDownIcon } from 'lucide-vue-next';
import { lazyStrings } from '@/strings';

type FeatureStatus = 'disabled' | 'enabled';
type DetailsState = 'collapsed' | 'expanded';
type ToggleAvailability = 'available' | 'unavailable';

const props = defineProps<{
  id: string,
  title: string,
  summary: string,
  details: string,
  status: FeatureStatus,
  toggleAvailability: ToggleAvailability,
  toggleLabel: string,
  toggleTestId: string,
}>();

const emit = defineEmits<{
  (event: 'toggle'): void,
}>();

const detailsState = ref<DetailsState>('collapsed');
const isDetailsExpanded = computed(() => detailsState.value === 'expanded');
const detailsAriaLabel = computed(() =>
  lazyStrings.ExperimentalFeatureRow__details_for({ title: props.title }),
);

function toggleDetails() {
  switch (detailsState.value) {
  case 'collapsed':
    detailsState.value = 'expanded';
    return;
  case 'expanded':
    detailsState.value = 'collapsed';
    return;
  default: {
    const _ex: never = detailsState.value;
    throw new Error(`Unhandled details state: ${_ex}`);
  }
  }
}

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {
      // Export internal state and logic used only for testing here. Do not reference these in production logic.
      // ESLint-required for defineExpose.
    },
  }) || {}),
});

import "virtual:naidan-tailwind-css-module/863743dc6f8b1209faa7f0283b5f5ae17c93d888e1b37fafa893af6c11849442.js";
import "virtual:naidan-tailwind-css-module/99ac2e1bd89fe9a6355f5a2a59c61fdc414fb86ae4ec813fb4ca684a6a9589fb.js";
import "virtual:naidan-tailwind-css-module/a3154efa0826671513284a5b182b5e25f12969f3af47466221c301c35ccf6385.js";
import "virtual:naidan-tailwind-css-module/e40bc904c786b5e9b6d5d61d2c4dd934a3c92e31e2662ea2701aeab4186f30e5.js";
import "virtual:naidan-tailwind-css-module/ebecc4fd674ef82f183437255486fe38e6831e60d5730478c48be6aabd6a8f8f.js";
</script>

<template>
  <div
    tw-class="bg-white/70 dark:bg-gray-900/35"
    :data-testid="`${props.id}-row`"
  >
    <div tw-class="flex flex-wrap items-center gap-x-3 gap-y-3 px-4 py-3.5 sm:px-5">
      <div tw-class="flex h-9 w-9 items-center justify-center rounded-xl border border-gray-200 bg-white text-gray-500 shadow-sm dark:border-gray-800 dark:bg-gray-900 dark:text-gray-400">
        <slot name="icon" />
      </div>

      <div tw-class="min-w-[10rem] flex-1">
        <div tw-class="flex min-w-0 items-center gap-2">
          <h4 tw-class="text-sm font-bold leading-tight text-gray-900 dark:text-gray-100">
            {{ props.title }}
          </h4>
        </div>
        <p tw-class="mt-0.5 text-[11px] font-medium leading-4 text-gray-500 dark:text-gray-400">
          {{ props.summary }}
        </p>
      </div>

      <div tw-class="ml-auto flex shrink-0 items-center gap-3">
        <div
          :tw-class="['inline-flex shrink-0 items-center gap-1.5 text-[10px] font-bold uppercase tracking-wider', props.status === 'enabled' ? 'text-amber-700 dark:text-amber-300' : 'text-gray-500 dark:text-gray-400']"
        >
          <AlertTriangleIcon v-if="props.status === 'enabled'" tw-class="h-3.5 w-3.5" />
          {{ props.status === 'enabled' ? lazyStrings.ExperimentalFeatureRow__enabled() : lazyStrings.ExperimentalFeatureRow__disabled() }}
        </div>

        <div tw-class="flex shrink-0 items-center gap-2">
          <button
            type="button"
            tw-class="inline-flex items-center gap-1 rounded-lg px-2 py-1.5 text-[11px] font-semibold text-gray-500 transition-colors hover:bg-gray-100 hover:text-gray-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gray-400/40 dark:text-gray-400 dark:hover:bg-gray-800 dark:hover:text-gray-100"
            :aria-expanded="isDetailsExpanded"
            :aria-controls="`${props.id}-details`"
            :data-testid="`${props.id}-details-toggle`"
            @click="toggleDetails"
          >
            {{ lazyStrings.ExperimentalFeatureRow__details() }}
            <ChevronDownIcon
              :tw-class="['h-3.5 w-3.5 transition-transform duration-200 motion-reduce:transition-none', isDetailsExpanded ? 'rotate-180' : '']"
            />
          </button>

          <button
            type="button"
            role="switch"
            :tw-class="['relative inline-flex h-5 w-9 shrink-0 items-center rounded-full transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500/40 focus-visible:ring-offset-2 focus-visible:ring-offset-white disabled:cursor-not-allowed disabled:opacity-60 dark:focus-visible:ring-offset-gray-950', props.status === 'enabled' ? 'bg-amber-500 dark:bg-amber-400' : 'bg-gray-300 dark:bg-gray-700']"
            :disabled="props.toggleAvailability === 'unavailable'"
            :aria-checked="props.status === 'enabled'"
            :aria-label="props.toggleLabel"
            :data-testid="props.toggleTestId"
            @click="emit('toggle')"
          >
            <span
              :tw-class="['block h-3.5 w-3.5 rounded-full bg-white shadow-sm transition-transform duration-200 motion-reduce:transition-none', props.status === 'enabled' ? 'translate-x-[18px]' : 'translate-x-[3px]']"
            />
          </button>
        </div>
      </div>
    </div>

    <div
      :id="`${props.id}-details`"
      :tw-class="['grid transition-[grid-template-rows] duration-200 ease-out motion-reduce:transition-none', isDetailsExpanded ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]']"
      role="region"
      :aria-hidden="!isDetailsExpanded"
      :aria-label="detailsAriaLabel"
      :data-testid="`${props.id}-details`"
    >
      <div tw-class="overflow-hidden">
        <div
          :tw-class="['px-4 pb-4 transition-[opacity,transform] duration-200 ease-out motion-reduce:transition-none sm:px-5', isDetailsExpanded ? 'translate-y-0 opacity-100' : '-translate-y-1 opacity-0']"
        >
          <p tw-class="ml-12 rounded-lg border border-gray-200/80 bg-gray-50/80 px-3 py-2 text-[11px] font-medium leading-relaxed text-gray-600 dark:border-gray-800 dark:bg-gray-950/35 dark:text-gray-300">
            {{ props.details }}
          </p>
        </div>
      </div>
    </div>
  </div>
</template>
